#include "Robotik/Task/Learning/EpisodeLog.hpp"

// Generated by the build: version and git commit of the library.
#include "project_info.hpp"

#include <cmath>
#include <iomanip>
#include <ostream>
#include <sstream>

namespace robotik
{

/// Escapes a string as a JSON string.
static std::string quoted(std::string_view p_text)
{
    std::string result = "\"";
    for (char const character : p_text)
    {
        if (character == '"' || character == '\\')
        {
            result += '\\';
        }
        result += character;
    }
    return result + "\"";
}

/// Prints a finite number at full precision, or null.
static std::string number(double p_value)
{
    if (!std::isfinite(p_value))
    {
        return "null";
    }
    std::ostringstream stream;
    stream << std::setprecision(17) << p_value;
    return stream.str();
}

/// Writes one observation or action space as a JSON array.
static void writeSpace(std::ostream& p_out, Space const& p_space)
{
    p_out << '[';
    for (std::size_t i = 0; i < p_space.dimensions.size(); ++i)
    {
        Space::Dimension const& dimension = p_space.dimensions[i];
        p_out << (i == 0U ? "" : ", ")
              << "{ \"name\": " << quoted(dimension.name)
              << ", \"low\": " << number(dimension.low)
              << ", \"high\": " << number(dimension.high)
              << ", \"unit\": " << quoted(dimension.unit)
              << ", \"privileged\": "
              << (dimension.privileged ? "true" : "false") << " }";
    }
    p_out << ']';
}

void writeEpisodeLog(EpisodeLog const& p_log,
                     std::ostream& p_out,
                     std::span<Episode const> p_episodes)
{
    p_out << "{\n  \"robotik\": { \"version\": "
          << quoted(project::info::version::full)
          << ", \"commit\": " << quoted(project::info::git::sha1) << " },\n"
          << "  \"scenario\": " << quoted(p_log.scenario) << ",\n"
          << "  \"policy\": " << quoted(p_log.policy) << ",\n"
          << "  \"master_seed\": " << p_log.master_seed << ",\n"
          << "  \"control_period\": " << number(p_log.control_period) << ",\n"
          << "  \"max_steps\": " << p_log.max_steps << ",\n"
          << "  \"observation\": ";
    writeSpace(p_out, p_log.observation);
    p_out << ",\n  \"action\": ";
    writeSpace(p_out, p_log.action);
    p_out << ",\n  \"episodes\": [";
    for (std::size_t i = 0; i < p_episodes.size(); ++i)
    {
        Episode const& episode = p_episodes[i];
        p_out << (i == 0U ? "\n" : ",\n")
              << "    { \"environment\": " << episode.environment
              << ", \"index\": " << episode.index
              << ", \"seed\": " << episode.seed.value
              << ", \"return\": " << number(episode.reward)
              << ", \"steps\": " << episode.steps
              << ", \"end\": " << quoted(toString(episode.end)) << " }";
    }
    p_out << (p_episodes.empty() ? "]\n}\n" : "\n  ]\n}\n");
}

} // namespace robotik
